package main

import (
	"crypto/subtle"
	"flag"
	"fmt"
	"net"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/mark3labs/mcp-go/server"
	"github.com/mvanhorn/printing-press-library/library/social-and-messaging/respondio/internal/cli"
	mcptools "github.com/mvanhorn/printing-press-library/library/social-and-messaging/respondio/internal/mcp"
)

// Transport selection order: --transport flag, then PP_MCP_TRANSPORT env,
// then the first transport declared in the spec (see MCPConfig.Transport).
// The flag surface lets one binary serve stdio locally and streamable HTTP
// when hosted in a container or remote sandbox, matching the Anthropic
// guidance that production agents need a remote option.

// defaultHTTPAddr binds loopback only. The HTTP transport serves every tool in
// this server, including mutations (send messages, delete contacts, modify
// tags), and those tools carry the operator's Respond.io token — but the
// streamable-HTTP transport has no inbound authentication of its own, so a
// wildcard bind would expose credentialed workspace tooling to anything that
// can reach the port. Hosted deployments that genuinely need a wider bind must
// opt in explicitly with --addr (e.g. --addr 0.0.0.0:7777) behind their own
// authenticating proxy, or set RESPONDIO_MCP_AUTH_TOKEN so this binary enforces
// a shared bearer secret on the non-loopback bind.
const (
	defaultHTTPAddr = "127.0.0.1:7777"
	// mcpEndpointPath is the library default endpoint path for the
	// streamable-HTTP transport (server.NewStreamableHTTPServer's own
	// default). Mounting at the same path keeps client routing unchanged.
	mcpEndpointPath = "/mcp"
	// mcpAuthEnv is the shared-secret env var required for non-loopback binds.
	mcpAuthEnv = "RESPONDIO_MCP_AUTH_TOKEN"
)

// version is the printed MCP server's version, overridable at build time via ldflags.
var version = "2026.8.7"

func main() {
	// Pin the learn-event surface for this process and every walker
	// shell-out child, so usage events record surface=mcp.
	_ = os.Setenv("RESPONDIO_LEARN_SURFACE", "mcp")
	if err := cli.BindMCPServerProfile(); err != nil {
		fmt.Fprintf(os.Stderr, "MCP client-profile bind failed: %v\n", err)
		os.Exit(1)
	}
	s := server.NewMCPServer(
		"Respondio",
		version,
		server.WithToolCapabilities(false),
	)

	mcptools.RegisterTools(s)

	transport := flag.String("transport", defaultTransport(), "MCP transport: stdio | http")
	addr := flag.String("addr", defaultHTTPAddr, "bind address for http transport (host:port or :port)")
	flag.Parse()

	switch strings.ToLower(*transport) {
	case "stdio":
		if err := server.ServeStdio(s); err != nil {
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(1)
		}
	case "http":
		httpSrv := server.NewStreamableHTTPServer(s)
		guarded, authEnabled, err := buildHTTPHandler(httpSrv, *addr)
		if err != nil {
			// Failing closed is the point: a non-loopback bind without a
			// shared secret is refused rather than served unauthenticated.
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(1)
		}
		mux := http.NewServeMux()
		mux.Handle(mcpEndpointPath, guarded)
		// Built here rather than via httpSrv.Start so the streamable-HTTP
		// handler can be mounted behind the auth guard while preserving the
		// library's default /mcp routing exactly.
		srv := &http.Server{
			Addr:              *addr,
			Handler:           mux,
			ReadHeaderTimeout: 10 * time.Second,
		}
		if authEnabled {
			fmt.Fprintf(os.Stderr, "respondio-pp-mcp serving MCP over streamable HTTP at %s (bearer auth required)\n", *addr)
		} else {
			fmt.Fprintf(os.Stderr, "respondio-pp-mcp serving MCP over streamable HTTP at %s\n", *addr)
		}
		if err := srv.ListenAndServe(); err != nil {
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(1)
		}
	default:
		fmt.Fprintf(os.Stderr, "unknown --transport %q (supported: stdio, http)\n", *transport)
		os.Exit(2)
	}
}

// defaultTransport reads PP_MCP_TRANSPORT env when set, otherwise falls back
// to "stdio" so running the binary with no args keeps today's behavior.
// Container-hosted agents can pin the transport via env without a flag, which
// matches how hosted-agent process supervisors typically pass configuration.
func defaultTransport() string {
	if t := os.Getenv("PP_MCP_TRANSPORT"); t != "" {
		return t
	}
	return "stdio"
}

// isLoopbackHost reports whether the host portion of addr binds loopback only.
// An empty host (":7777", all interfaces) is NOT loopback.
func isLoopbackHost(addr string) bool {
	host := addr
	if h, _, err := net.SplitHostPort(addr); err == nil {
		host = h
	}
	// Strip any IPv6 zone suffix (e.g. "::1%lo0").
	if i := strings.Index(host, "%"); i >= 0 {
		host = host[:i]
	}
	switch host {
	case "127.0.0.1", "::1", "localhost":
		return true
	}
	return false
}

// buildHTTPHandler returns the http.Handler for the streamable-HTTP transport
// at the given bind addr. Loopback binds serve the MCP handler unguarded so
// local stdio-style usage stays frictionless. Any other bind requires a shared
// secret in RESPONDIO_MCP_AUTH_TOKEN; without one the bind is refused (error)
// rather than served unauthenticated, and with one every request must carry
// Authorization: Bearer <token>. The bool reports whether auth is enabled so
// main can state it in the startup line without echoing the token value.
func buildHTTPHandler(httpSrv http.Handler, addr string) (http.Handler, bool, error) {
	if isLoopbackHost(addr) {
		return httpSrv, false, nil
	}
	token := os.Getenv(mcpAuthEnv)
	if token == "" {
		return nil, false, fmt.Errorf("non-loopback MCP bind %q requires %s; set it, or bind loopback and front the server with an authenticating proxy", addr, mcpAuthEnv)
	}
	return &bearerGuard{inner: httpSrv, token: token}, true, nil
}

// bearerGuard wraps an http.Handler and requires every request to carry
// `Authorization: Bearer <token>`, compared with a constant-time compare so
// a timing side channel can't leak the secret. On a missing or mismatched
// credential it responds 401 without calling through to the wrapped handler.
type bearerGuard struct {
	inner http.Handler
	token string
}

func (g *bearerGuard) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	const prefix = "Bearer "
	auth := r.Header.Get("Authorization")
	if !strings.HasPrefix(auth, prefix) {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}
	supplied := strings.TrimSpace(auth[len(prefix):])
	if subtle.ConstantTimeCompare([]byte(supplied), []byte(g.token)) != 1 {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}
	g.inner.ServeHTTP(w, r)
}
